// The protocol wire types (`SessionMeta`, `ServerMsg`) live in the sibling `protocol`
// module; the parent `state` reaches them via `use super::protocol::*`, so a child record
// imports the parent namespace to keep resolving them after decomposition.
use super::*;

/// Build a `session_state` event from a pushed snapshot.
pub(crate) fn session_state_msg(s: &SessionMeta) -> ServerMsg {
    ServerMsg::SessionState {
        pane_id: s.pane_id.clone(),
        status: s.status.clone(),
        current_task: s.current_task.clone(),
        last_activity: s.last_activity.clone(),
        prompt: s.prompt.clone(),
    }
}
